  const els = $$('#unit .book'); if (els.length) return els.map(el => ({id: el.dataset.id, r: +el.dataset.row, x: parseFloat(el.style.left)})).sort((a, b) => a.r - b.r || a.x - b.x).map(o => o.id);
  return sorted(books.slice()).map(b => b.id);
