  const setT = () => bx.style.transform = `rotateX(${rx}deg) rotateY(${ry}deg)`;
  bx.addEventListener('animationend', () => { bx.classList.remove('in'); setT(); bx.style.transition = 'transform .5s ease-out'; });
  const down = e => { dn = {x: e.clientX, y: e.clientY, ry, rx}; bx.classList.remove('in'); bx.style.transition = 'none'; v.style.cursor = 'grabbing'; e.preventDefault(); };
