function reviewReasons18(b){if(reviewCache18.has(b.id))return reviewCache18.get(b.id);if(b.wish)return [];const reasons=[];if(b.unknown||!b.title)reasons.push('unknown');if((b.scanConfidence??b.confidence)!=null&&+(b.scanConfidence??b.confidence)<.75)reasons.push('uncertain');if(!b.cover)reasons.push('cover');if(books.some(o=>o.id!==b.id&&!o.wish&&sameEdition18(o,b)))reasons.push('duplicate');if(b.reviewValidated===reviewFingerprint18(b)){reviewCache18.set(b.id,[]);return [];}reviewCache18.set(b.id,reasons);return reasons;}
