function showRereadResults18(results){openModal(`<div class="dhead"><h3>Vérifier la nouvelle lecture</h3><button class="x" data-close>×</button></div><div class="mbody"><p class="hint">Vérifie les propositions. Les notes, la couverture et l’emplacement restent inchangés.</p>${results.map((r,i)=>`<div data-rr="${i}" class="enhance-result"><label><input type="checkbox" data-rr-use ${r.res?.titre?'checked':'disabled'}> Appliquer</label><p data-no-i18n>Avant : ${esc(dispTitle(r.book))} · ${esc(r.book.author)}</p>${r.res?`<label class="l">Titre</label><input class="fld" data-rr-title value="${esc(r.res.titre||'')}"><label class="l">Auteur</label><input class="fld" data-rr-author value="${esc(r.res.auteur||'')}"><div class="g2"><div><label class="l">Série</label><input class="fld" data-rr-series value="${esc(r.res.serie||'')}"></div><div><label class="l">Tome</label><input class="fld" type="number" data-rr-volume value="${parseInt(r.res.tome)||''}"></div></div>`:'<p>Lecture non concluante. Reprendre une photo rapprochée.</p>'}</div>`).join('')}<button type="button" class="btn p" id="rrApply">Appliquer les propositions choisies</button></div>`);$('#rrApply').onclick=async()=>{const selected=$$('[data-rr]').filter(e=>e.querySelector('[data-rr-use]').checked);if(!selected.length)return;if(!await safetyPoint18('Avant relecture IA'))return;for(const el of selected){const r=results[+el.dataset.rr],b=r.book,title=el.querySelector('[data-rr-title]').value.trim();if(!title)continue;Object.assign(b,{title,author:el.querySelector('[data-rr-author]').value.trim(),series:el.querySelector('[data-rr-series]').value.trim(),volume:parseInt(el.querySelector('[data-rr-volume]').value)||null,unknown:false,scanConfidence:null,confidence:null,reviewReadAt:Date.now()});delete b.reviewValidated;await saveBook(b);}closeModal();renderAll();toast('Propositions enregistrées');};}
