function renderWishlist18(){const root=$('#v-wish');if(!root)return;const rows=wishRows18(),all=books.filter(b=>b.wish),priced=all.filter(b=>Number(b.wishTarget)>0),total=priced.reduce((n,b)=>n+Number(b.wishTarget),0);root.innerHTML=`<div class="enhance-head"><h2>Liste de souhaits <span class="badge">${all.length}</span></h2><button type="button" class="btn p" id="wishNew">Ajouter un souhait</button></div><p class="hint">Budget cible renseigné : ${total.toFixed(2)} € pour ${priced.length} souhait(s). Les prix et liens sont saisis par toi, sans suivi automatique.</p><div class="enhance-filters"><input class="fld" id="wishSearch" value="${esc(WISH18.q)}" placeholder="Rechercher"><select class="fld" id="wishPriority"><option value="">Toutes priorités</option><option value="high" ${WISH18.priority==='high'?'selected':''}>Haute</option><option value="normal" ${WISH18.priority==='normal'?'selected':''}>Normale</option><option value="low" ${WISH18.priority==='low'?'selected':''}>Basse</option></select><select class="fld" id="wishSort"><option value="priority">Priorité puis série</option><option value="title" ${WISH18.sort==='title'?'selected':''}>Titre</option><option value="price" ${WISH18.sort==='price'?'selected':''}>Prix cible</option></select></div><div class="enhance-grid">${rows.slice(0,WISH18.limit).map(b=>{const dup=wishDuplicates18(b),url=safeBuyLink18(b.wishLink);return `<article class="enhance-card"><div class="enhance-cover">${coverHTML(b)}</div><div><h3 data-no-i18n>${esc(dispTitle(b))}</h3><p data-no-i18n>${esc(b.author)}${b.series?' · '+esc(b.series)+(b.volume?' · '+b.volume:''):''}</p><span class="badge">${{high:'Haute',normal:'Normale',low:'Basse'}[wishPriority18(b)]}</span>${b.wishTarget?`<span class="badge">${Number(b.wishTarget).toFixed(2)} €</span>`:''}<p data-no-i18n>${esc(b.wishReason||'')}</p>${dup.length?`<p class="badge k">${dup.some(o=>!o.wish)?'Déjà possédé':'Déjà souhaité'}</p>`:''}<div class="btns"><button type="button" class="btn s sm" data-wish-edit="${b.id}">Modifier</button><button type="button" class="btn p sm" data-wish-buy="${b.id}">Acheté › Ranger</button>${url?`<a class="btn s sm" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Lien d’achat</a>`:''}<button type="button" class="btn s sm" data-wish-delete="${b.id}">Supprimer</button></div></div></article>`;}).join('')||'<p>Aucun souhait.</p>'}</div>${rows.length>WISH18.limit?'<button type="button" class="btn s" id="wishMore">Afficher davantage</button>':''}`;
 $('#wishNew').onclick=()=>openWishForm18();$('#wishSearch').onchange=e=>{WISH18.q=e.target.value;WISH18.limit=60;renderWishlist18();};$('#wishPriority').onchange=e=>{WISH18.priority=e.target.value;renderWishlist18();};$('#wishSort').onchange=e=>{WISH18.sort=e.target.value;renderWishlist18();};if($('#wishMore'))$('#wishMore').onclick=()=>{WISH18.limit+=60;renderWishlist18();};root.onclick=async e=>{const a=e.target.closest('[data-wish-edit],[data-wish-buy],[data-wish-delete]');if(!a)return;const id=a.dataset.wishEdit||a.dataset.wishBuy||a.dataset.wishDelete,b=books.find(b=>b.id===id);if(a.dataset.wishEdit){NAV.list=wishRows18().map(b=>b.id);openBook(id,false,true);}else if(a.dataset.wishBuy)openWishPurchase18(b);else await deleteBooks([id],'Souhait supprimé');};
}
function wishFields18(b){return `<div class="step">Liste de souhaits</div><div class="g2"><div><label class="l">Priorité</label><select class="fld" id="eWishPriority">${[['high','Haute'],['normal','Normale'],['low','Basse']].map(([k,v])=>`<option value="${k}" ${wishPriority18(b)===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label class="l">Prix cible (€)</label><input class="fld" type="number" min="0" step="0.01" id="eWishTarget" value="${esc(b.wishTarget??'')}"></div></div><label class="l">Motif du souhait</label><input class="fld" id="eWishReason" value="${esc(b.wishReason||'')}"><label class="l">Lien d’achat facultatif</label><input class="fld" type="url" id="eWishLink" value="${esc(b.wishLink||'')}"><p class="hint">Les prix et liens ne sont pas vérifiés automatiquement.</p>${wishDuplicates18(b).length?'<p class="badge k">Livre déjà possédé ou déjà souhaité : vérifie avant d’acheter.</p>':''}`;}
function readWishFields18(b){if(!$('#eWishPriority'))return;const price=$('#eWishTarget').value.trim();b.wishPriority=$('#eWishPriority').value;b.wishTarget=price===''?null:clamp(Number(price)||0,0,100000);b.wishReason=$('#eWishReason').value.trim();b.wishLink=safeBuyLink18($('#eWishLink').value.trim());}
function openWishForm18(){openModal(`<div class="dhead"><h3>Ajouter un souhait</h3><button class="x" data-close>×</button></div><div class="mbody"><label class="l">Titre</label><input class="fld" id="wishTitle"><label class="l">Auteur</label><input class="fld" id="wishAuthor"><div class="g2"><div><label class="l">Série</label><input class="fld" id="wishSeries"></div><div><label class="l">Tome</label><input class="fld" type="number" min="1" id="wishVolume"></div></div><label class="l">ISBN</label><input class="fld" id="wishISBN">${wishFields18({})}<button type="button" class="btn p" id="wishCreate">Ajouter un souhait</button><p id="wishMsg" aria-live="polite"></p></div>`,'sm');$('#wishCreate').onclick=async()=>{const create=$('#wishCreate');if(create.disabled)return;const b=newBook({title:$('#wishTitle').value.trim(),author:$('#wishAuthor').value.trim(),series:$('#wishSeries').value.trim(),volume:parseInt($('#wishVolume').value)||null,isbn:$('#wishISBN').value.trim(),wish:true,caseId:null,position:null});if(!b.title){$('#wishMsg').textContent='Le titre est obligatoire';return;}readWishFields18(b);const dup=wishDuplicates18(b);if(dup.length&&!confirm('Ce livre est déjà possédé ou souhaité. Ajouter quand même ?'))return;create.disabled=true;try{await saveBook(b);closeModal();renderAll();setView('wish');}finally{if(create.isConnected)create.disabled=false;}};}
function openWishPurchase18(b){if(!b?.wish)return;const owned=wishDuplicates18(b).filter(o=>!o.wish);openModal(`<div class="dhead"><h3>Acheté › Ranger</h3><button class="x" data-close>×</button></div><div class="mbody"><h3 data-no-i18n>${esc(dispTitle(b))}</h3>${owned.length?'<p class="badge k">Ce livre est déjà possédé. Vérifie l’édition.</p>':''}<label class="l">Meuble</label><select class="fld" id="purchaseCase" data-no-i18n>${cases.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}<option value="__new">Nouveau meuble…</option></select><label class="l">Étagère</label><input class="fld" type="number" min="1" max="15" value="1" id="purchaseRow"><label class="l">Position (vide = à la fin)</label><input class="fld" type="number" min="1" id="purchasePos"><label class="l">Prix payé (€), facultatif</label><input class="fld" type="number" min="0" step=".01" id="purchasePrice"><button type="button" class="btn p" id="purchaseSave">Ranger le livre acheté</button></div>`,'sm');$('#purchaseSave').onclick=async()=>{if(owned.length&&!confirm('Ranger un exemplaire supplémentaire ?'))return;if(!await safetyPoint18('Avant achat et rangement'))return;let cid=$('#purchaseCase').value;if(cid==='__new'){const name=prompt('Nom du nouveau meuble :','Nouveau meuble');if(!name)return;cid=(await newCase(name)).id;}const row=clamp(parseInt($('#purchaseRow').value)||1,1,15),pos=parseInt($('#purchasePos').value)||null,price=$('#purchasePrice').value.trim(),c=cases.find(c=>c.id===cid);b.wish=false;b.wishPurchasedAt=new Date().toISOString();b.caseId=cid;b.row=row;b.addedAt=Date.now();if(price!==''){b.price=clamp(Number(price)||0,0,100000);b.priceSource='Manuel';}const list=books.filter(o=>o.id!==b.id&&o.caseId===cid&&(o.row||1)===row&&!o.wish).sort((a,c)=>(a.position||999)-(c.position||999));list.splice(pos?clamp(pos-1,0,list.length):list.length,0,b);list.forEach((o,i)=>o.position=i+1);if(c&&c.rows<row){c.rows=row;await DB.put('cases',c);}await DB.putMany('books',list);await saveBook(b);closeModal();renderAll();openBook(b.id,false,true);toast('Ajouté à ta collection');};}
function safetyDB18(){if(SAFETY18.db)return Promise.resolve(SAFETY18.db);return new Promise((resolve,reject)=>{const req=indexedDB.open('SCANLY_SafetyPoints',1);req.onupgradeneeded=()=>req.result.createObjectStore('points',{keyPath:'id'});req.onsuccess=()=>{SAFETY18.db=req.result;resolve(req.result);};req.onerror=()=>reject(req.error);});}
async function safetyPoint18(label,mandatory=true){if(SAFETY18.restoring)return true;const task=SAFETY18.queue.then(async()=>{try{const db=await safetyDB18(),point={id:Date.now()+'_'+uid(),at:Date.now(),label,version:VERSION,books:await DB.allRaw('books'),cases:await DB.allRaw('cases'),imports:await DB.allRaw('imports'),trash:await DB.allRaw('trash'),seriesMeta:JSON.parse(JSON.stringify(SMETA)),theme};await new Promise((resolve,reject)=>{const tx=db.transaction('points','readwrite'),store=tx.objectStore('points');store.put(point);const req=store.getAll();req.onsuccess=()=>req.result.sort((a,b)=>b.at-a.at).slice(3).forEach(p=>store.delete(p.id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});return true;}catch(e){return mandatory?confirm('Point de restauration impossible (stockage plein ou indisponible). Continuer sans cette protection ?'):false;}});SAFETY18.queue=task.catch(()=>{});return task;}
async function openSafety18(){const db=await safetyDB18();const points=await new Promise((resolve,reject)=>{const r=db.transaction('points').objectStore('points').getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>b.at-a.at));r.onerror=()=>reject(r.error);});openModal(`<div class="dhead"><h3>Points de restauration</h3><button class="x" data-close>×</button></div><div class="mbody"><p class="hint">Trois états complets sont conservés sur cet appareil, hors synchronisation. Restaurer remplace la bibliothèque locale. Une sauvegarde exportée reste recommandée.</p><button type="button" class="btn s" id="safetyNew">Créer un point maintenant</button>${points.map((p,i)=>`<div class="enhance-result"><b>${esc(p.label)}</b><p>${new Date(p.at).toLocaleString('fr-FR')} · ${p.books.length} livres</p><button type="button" class="btn s" data-safety="${i}">Restaurer</button></div>`).join('')||'<p>Aucun point disponible.</p>'}</div>`);$('#safetyNew').onclick=async()=>{if(await safetyPoint18('Point manuel'))openSafety18();};$$('[data-safety]').forEach(btn=>btn.onclick=async()=>{const p=points[+btn.dataset.safety];if(!confirm('Remplacer la bibliothèque locale par ce point de restauration ?'))return;if(!await safetyPoint18('Avant restauration'))return;if(SY.busy)return toast('Termine la synchronisation avant de restaurer.');clearTimeout(SY.timer);localStorage.setItem('scanly_sync_auto','0');SAFETY18.restoring=true;try{await new Promise((resolve,reject)=>{const tx=DB.db.transaction(['books','cases','imports','trash'],'readwrite');for(const k of ['books','cases','imports','trash']){const st=tx.objectStore(k);st.clear();(p[k]||[]).forEach(o=>st.put(o));}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});SMETA=p.seriesMeta||{};localStorage.setItem('scanly_series',JSON.stringify(SMETA));if(p.theme&&THEMES[p.theme]){theme=p.theme;localStorage.setItem('scanly_theme',theme);rt=activeTheme();applyTheme();}await load();SEL.clear();SY.dirty=true;SY.last=null;UNDO.stack=[];UNDO.redo=[];persistUndo();closeModal();renderAll();toast('Bibliothèque restaurée. Vérifie avant de synchroniser.');}finally{SAFETY18.restoring=false;}});}
function toolSaveNext18(b,kind,selector){const save=$(selector);if(!save)return;const list=toolList(b,kind),id=list[list.indexOf(b.id)+1];const btn=document.createElement('button');btn.type='button';btn.className='btn p';btn.id='toolSaveNext';btn.textContent='Enregistrer et suivant';btn.disabled=!id||save.disabled;save.after(btn);const observer=new MutationObserver(()=>btn.disabled=!id||save.disabled);observer.observe(save,{attributes:true,attributeFilter:['disabled']});const prev=modalExtraCleanup;modalExtraCleanup=()=>{prev?.();observer.disconnect();};btn.onclick=async()=>{if(btn.disabled)return;btn.disabled=true;const old=b.updatedAt;try{await save.onclick?.({currentTarget:save,target:save});if(b.updatedAt===old&&!(!save.isConnected&&books.some(o=>o.id===b.id)))return;modalLeaveGuard=null;closeModal();NAV.cur=id;openBook(id,false,true);await openBookTool(books.find(o=>o.id===id),kind);}finally{if(btn.isConnected)btn.disabled=!id||save.disabled;}};}
function nextCompare18(b,kind){const src=b.spineImg;if(!src)return;const image=$('#qePrev')||$('#spI');if(!image)return;const wrapper=document.createElement('details');wrapper.className='enhance-compare';wrapper.innerHTML=`<summary>Comparer avant / après</summary><div class="enhance-compare-grid"><div><p>Avant</p><img src="${src}"></div><div><p>Aperçu</p><img id="compareAfter18" src="${image.src}"></div></div>`;$('#mbox .mbody').prepend(wrapper);const obs=new MutationObserver(()=>{const after=$('#compareAfter18');if(after)after.src=image.src;});obs.observe(image,{attributes:true,attributeFilter:['src']});const prev=modalExtraCleanup;modalExtraCleanup=()=>{prev?.();obs.disconnect();};}
async function photoQuality18(src){const im=await srcToImg(src),w=imgW(im),h=imgH(im),c=document.createElement('canvas'),k=Math.min(1,800/Math.max(w,h));c.width=Math.round(w*k);c.height=Math.round(h*k);const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0,c.width,c.height);const data=x.getImageData(0,0,c.width,c.height).data,gray=i=>(data[i]*.299+data[i+1]*.587+data[i+2]*.114);let n=0,sum=0,sum2=0,glare=0;for(let y=1;y<c.height-1;y+=2)for(let a=1;a<c.width-1;a+=2){const i=(y*c.width+a)*4,g=gray(i),lap=gray(i-4)+gray(i+4)+gray(i-c.width*4)+gray(i+c.width*4)-4*g;n++;sum+=lap;sum2+=lap*lap;if(g>248)glare++;}const variance=n?sum2/n-(sum/n)**2:0;return {w,h,blur:variance<35,glare:n?glare/n:0,low:w<1000||h<400,wide:w/Math.max(1,h)>4,variance};}
async function checkPhotos18(urls){const warnings=[];for(let i=0;i<urls.length;i++){try{const q=await photoQuality18(urls[i]),r=[];if(q.low)r.push('résolution limitée');if(q.blur)r.push('netteté possiblement insuffisante');if(q.wide)r.push('photo très large : plusieurs clichés rapprochés peuvent aider');if(q.glare>.2)r.push('zones très claires : vérifier les reflets');if(r.length)warnings.push(`Photo ${i+1} (${q.w} × ${q.h}) : ${r.join(', ')}`);}catch(e){warnings.push(`Photo ${i+1} : contrôle impossible`);}}return !warnings.length||confirm(warnings.join('\n')+'\n\nContrôle indicatif, sans garantie. Continuer le scan ?');}
function enhanceModal18(){const body=$('#mbox .mbody');if(!body)return;body.classList.add('enhanced-tools');body.querySelectorAll('p.hint').forEach(p=>{if(p.textContent.length<140||p.closest('details'))return;const d=document.createElement('details');d.className='enhance-help';const summary=document.createElement('summary');summary.textContent='Aide';p.before(d);d.append(summary,p);});
 /* V2.20 : les boutons d'action sont DÉPLACÉS (et non copiés) dans la barre fixe : une seule commande par action. */
 const actions=['#qeOk','#straightRun','#straightSave','#spOk','#cropApply','#ogRep','#ogAdd','#zoneApply','#rrApply','#purchaseSave','#filterReset19','#filterApply19','#toolSaveNext'].map(sel=>$(sel)).filter(Boolean);
 const old=$('#mbox .tool-action-dock');if(!actions.length){old?.remove();return;}
 const dock=document.createElement('div');dock.className='tool-action-dock';const sources=new Set();
 const isCancel=el=>el.tagName==='BUTTON'&&!el.classList.contains('x')&&(el.hasAttribute('data-close')||el.dataset.dockCancel==='1');
 let cancel=old?[...old.children].find(isCancel):null;
 actions.forEach(a=>{const parent=a.parentElement;if(parent&&parent!==old)sources.add(parent);});
 for(const parent of sources){const c=[...parent.querySelectorAll(':scope > button')].find(isCancel);if(c){if(!cancel)cancel=c;else if(c!==cancel)c.remove();}}
 if(!cancel){cancel=document.createElement('button');cancel.type='button';cancel.className='btn s';cancel.textContent='Annuler';cancel.setAttribute('data-close','');}
 cancel.dataset.dockCancel='1';dock.appendChild(cancel);const spacer=document.createElement('span');spacer.className='tsp';dock.appendChild(spacer);
 actions.forEach(a=>dock.appendChild(a));
 for(const parent of sources){if(![...parent.children].some(el=>!el.classList.contains('tsp')&&el.style.display!=='none'))parent.remove();}
 old?.remove();$('#mbox').appendChild(dock);}

function attachToolEnhance18(b,kind){const selector={quad:'#qeOk',straight:'#straightSave',split:'#spOk',cover:'#cropApply',back:'#cropApply',origin:'#ogRep'}[kind];if(selector)toolSaveNext18(b,kind,selector);if(kind==='quad')nextCompare18(b,kind);enhanceModal18();}
function holdDelay18(){return {short:450,normal:600,long:900}[localStorage.getItem('scanly_hold_delay')]||600;}
async function editionPicker18(b){const original=JSON.parse(JSON.stringify(b));openModal(`<div class="dhead"><h3>Choisir une édition</h3><button class="x" data-close>×</button></div><div class="mbody"><p class="hint">Vérifie titre, tome, éditeur, année et ISBN. Une couverture personnelle reste protégée. Aucune édition n’est appliquée automatiquement.</p><div class="g2"><div><label class="l">Série à conserver ou corriger</label><input class="fld" id="editionSeries" value="${esc(b.series||'')}"></div><div><label class="l">Tome lu sur l’édition (ne pas déduire)</label><input class="fld" type="number" min="1" id="editionVolume" value="${b.volume||''}"></div></div><div id="editionRows" aria-live="polite">Recherche…</div></div>`);try{let items=await gBooks(b.isbn?'isbn:'+b.isbn:'intitle:'+b.title+(b.author?' inauthor:'+b.author:''),8);const rows=items.map(it=>{const v=it.volumeInfo||{},ids=v.industryIdentifiers||[];return {it,title:v.title,subtitle:v.subtitle,author:(v.authors||[]).join(', '),publisher:v.publisher,year:v.publishedDate,isbn:(ids.find(x=>x.type==='ISBN_13')||ids[0])?.identifier,cover:v.imageLinks?.thumbnail||v.imageLinks?.smallThumbnail,source:'Google Books'};});if(b.isbn){const ol=await olByIsbn(b.isbn);if(ol)rows.push({title:ol.title,subtitle:ol.subtitle,author:(ol.author_name||[]).join(', '),publisher:(ol.publisher||[])[0],year:ol.publish_year?.[0],isbn:b.isbn,cover:ol.coverUrl,source:'Open Library',ol});}const root=$('#editionRows');if(!root)return;root.innerHTML=rows.map((r,i)=>`<article class="enhance-card"><img src="${esc((r.cover||'').replace('http:','https:'))}" style="max-width:90px;max-height:130px;object-fit:contain" alt=""><div data-no-i18n><h3>${esc(r.title)}</h3><p>${esc(r.subtitle||'')}<br>${esc(r.author)}<br>${esc(r.publisher||'')} · ${esc(r.year||'')}<br>ISBN ${esc(r.isbn||'')} · ${r.source}</p></div><button type="button" class="btn s" data-edition="${i}">Choisir cette édition</button></article>`).join('')||'<p>Aucune édition trouvée. Vérifie l’ISBN ou utilise la BnF.</p>';root.onclick=async e=>{const btn=e.target.closest('[data-edition]');if(!btn)return;const r=rows[+btn.dataset.edition];if(!confirm('Remplacer les informations bibliographiques par cette édition ? Notes, statut et emplacement sont conservés.'))return;if(!await safetyPoint18('Avant choix d’édition'))return;if(r.it){applyGB(b,r.it,true);b.title=r.title||b.title;}else{for(const k of ['title','author','publisher','isbn'])if(r[k])b[k]=r[k];if(r.year)b.year=parseInt(r.year)||b.year;if(r.ol.number_of_pages_median)b.pages=r.ol.number_of_pages_median;if(!b.coverManual&&r.cover)b.cover=r.cover;}b.series=$('#editionSeries').value.trim();b.volume=parseInt($('#editionVolume').value)||null;b.editionSource=r.source;b.unknown=false;await saveBook(b);closeModal();renderAll();openBook(b.id,false,true);};}catch(e){if($('#editionRows'))$('#editionRows').textContent=e.message;}}

/* V2.19: compact filters, ISBN form autofill and short grounded story preview. */
function filterCount19(){return ['type','status','author','genre'].filter(k=>F[k]).length+(F.sort!=='shelf'?1:0);}
function renderCompactFilters19(){const btn=$('#filtersOpen19');if(!btn)return;const n=filterCount19();btn.innerHTML=`<span>Filtres</span>${n?` <b class="filter-count19">${n}</b>`:''} <span aria-hidden="true">▾</span>`;btn.title=n?['type','status','author','genre'].filter(k=>F[k]).map(k=>F[k]).join(' · '):'Type, statut, auteur, genre et tri';btn.classList.toggle('active',n>0);$('#filterClear19').hidden=!n;const select=$('#viewCompact19');if(select){const active=$('#viewSeg button.on');if(active)select.value=active.dataset.v;}}
