 openModal(`<div class="dhead"><h3>Analyse de la zone</h3></div><div class="mbody"><p id="sMsg" aria-live="polite">Lecture IA…</p><p class="hint">Aucune modification de la bibliothèque avant validation.</p></div>`,'sm');modalLeaveGuard=()=>false;
 try{const img=await srcToImg(result.src),{list}=await recognize([result.src]);
  records=list.filter(d=>Array.isArray(d.boite)&&d.boite.length===4&&d.boite.every(Number.isFinite)&&d.boite[2]>d.boite[0]&&d.boite[3]>d.boite[1]).slice(0,150).map(d=>{d.boite=d.boite.map(v=>clamp(v,0,1000));const sp=spineFromDetection(img,d.boite,d.coins),q=sp.quad||[[d.boite[1]/1000,d.boite[0]/1000],[d.boite[3]/1000,d.boite[0]/1000],[d.boite[3]/1000,d.boite[2]/1000],[d.boite[1]/1000,d.boite[2]/1000]],quad=q.map(p=>[result.rect.x+p[0]*result.rect.w,result.rect.y+p[1]*result.rect.h]);
   const candidates=books.filter(b=>b.caseId===anchor.caseId);let match=null,score=0;for(const b of candidates){let sc=0;if(!context.newPhoto&&b.quad&&(b.srcRef?.imp||b.importId)===context.imp?.id&&(b.srcRef?.pi??0)===context.pi){const a=quadBox(quad),c=quadBox(b.quad),inter=Math.max(0,Math.min(a.x1,c.x1)-Math.max(a.x0,c.x0))*Math.max(0,Math.min(a.y1,c.y1)-Math.max(a.y0,c.y0)),area=(a.x1-a.x0)*(a.y1-a.y0);sc=area?inter/area:0;}if(d.titre&&norm(d.titre)===norm(b.title)&&(parseInt(d.tome)||null)===(b.volume||null))sc=Math.max(sc,.8);if(sc>score){score=sc;match=b;}}
   const right=!context.newPhoto?candidates.filter(b=>!b.wish&&b.quad&&(b.srcRef?.imp||b.importId)===context.imp?.id&&(b.srcRef?.pi??0)===context.pi&&(b.row||1)===clamp((context.baseRow||anchor.row||1)+(parseInt(d.rangee)||1)-1,1,15)&&quadBox(b.quad).x0>quadBox(quad).x0).sort((a,b)=>quadBox(a.quad).x0-quadBox(b.quad).x0)[0]:null;
   return {d,sp,quad,beforeId:right?.id||'',title:d.titre||'',author:d.auteur||'',series:d.serie||'',volume:parseInt(d.tome)||null,row:clamp((context.baseRow||anchor.row||1)+(parseInt(d.rangee)||1)-1,1,15),match:score>.45?match:null,action:score>.45?'ignore':'add',target:score>.45?match.id:'',replaceInfo:false};});
 }catch(e){modalLeaveGuard=null;openModal(`<div class="dhead"><h3>Analyse interrompue</h3><button class="x" data-close>×</button></div><div class="mbody"><p>${esc(e.message)}</p><p>Aucun livre modifié.</p><button type="button" class="btn s" id="zoneRetry">Reprendre la zone</button></div>`,'sm');$('#zoneRetry').onclick=()=>openZoneTool(anchor);return;
 }finally{if(prevMode==null)localStorage.removeItem('scanly_mode');else localStorage.setItem('scanly_mode',prevMode);}
