 let applied=false,busy=false;modalLeaveGuard=()=>!busy&&(applied||confirm('Abandonner ces résultats non appliqués ? La bibliothèque reste inchangée.'));
 $('#zoneReview').onchange=e=>{const row=e.target.closest('[data-zr]'),key=e.target.dataset.zk;if(!row||!key)return;const r=records[+row.dataset.zr];r[key]=key==='replaceInfo'?e.target.checked:key==='volume'?(parseInt(e.target.value)||null):key==='row'?clamp(parseInt(e.target.value)||1,1,15):e.target.value;};
 $('#zoneReview').onclick=e=>{const crop=e.target.closest('[data-zone-crop]');if(crop){if(busy)return;modalLeaveGuard=null;openCandidateCrop(anchor,result,context,records,+crop.dataset.zoneCrop);return;}const btn=e.target.closest('[data-zone-split]');if(!btn)return;const i=+btn.dataset.zoneSplit,r=records[i];if(busy)return;modalLeaveGuard=null;openCandidateSplit(anchor,result,context,records,i);};
