function openLoupe(b) {
  const L = (NAV.list || navList()).filter(id => books.some(o => o.id === id && o.spineImg));
  if (!L.includes(b.id)) L.unshift(b.id);
  const idx = L.indexOf(b.id);
  openModal(`<div class="dhead"><h3 style="flex:1;min-width:0">${esc(dispTitle(b))}</h3><div style="display:flex;align-items:center;gap:8px"><button type="button" class="btn s sm" id="lpPrev" aria-label="Livre précédent" ${idx > 0 ? '' : 'disabled'}>‹</button><span aria-live="polite">${idx+1} / ${L.length}</span><button type="button" class="btn s sm" id="lpNext" aria-label="Livre suivant" ${idx < L.length-1 ? '' : 'disabled'}>›</button></div><button class="x" data-close>×</button></div><div class="mbody" style="padding:0">
    <div style="padding:8px 12px;display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="btn g sm" id="lpCorrect">Corriger sur la photo d’origine</button><span class="hint">Mode Consulter</span></div><div id="lpW" style="position:relative;height:74vh;overflow:hidden;background:#0b1220;cursor:grab"><img id="lpI" src="${spineURL(b)}" alt="" style="position:absolute;left:50%;top:50%;transform-origin:0 0;image-rendering:auto;user-select:none" draggable="false"></div>
    <p class="hint" style="padding:8px 16px;margin:0">Molette : zoom · glisser : déplacer · double-clic : ajuster</p></div>`, 'sm');
  $('#lpCorrect').onclick=()=>openOrigin(b,{integrated:true});
  const W = $('#lpW'), I = $('#lpI'); let z = 1, x = 0, y = 0, dn = null;
  const fit = () => { if(!I.naturalWidth||!I.naturalHeight||!W.isConnected)return; const k = Math.min(W.clientWidth * .9 / I.naturalWidth, W.clientHeight * .95 / I.naturalHeight); z = k; x = (W.clientWidth - I.naturalWidth * z) / 2; y = (W.clientHeight - I.naturalHeight * z) / 2; draw(); };
  const draw = () => { I.style.left = '0'; I.style.top = '0'; I.style.transform = `translate(${x}px,${y}px) scale(${z})`; };
  I.onload = fit; if (I.complete) setTimeout(fit, 0);
  W.addEventListener('wheel', e => { e.preventDefault(); const r = W.getBoundingClientRect(), mx = e.clientX - r.left, my = e.clientY - r.top, f = Math.exp(-e.deltaY * .0015), nz = clamp(z * f, .2, 30);
    x = mx - (mx - x) * nz / z; y = my - (my - y) * nz / z; z = nz; draw(); }, {passive: false});
  W.onmousedown = e => { dn = {x: e.clientX - x, y: e.clientY - y}; W.style.cursor = 'grabbing'; e.preventDefault(); };
  const mv = e => { if (!dn) return; x = e.clientX - dn.x; y = e.clientY - dn.y; draw(); }, up = () => { dn = null; if (W) W.style.cursor = 'grab'; };
  window.addEventListener('mousemove', mv); window.addEventListener('mouseup', up); W.ondblclick = fit;
  // Use explicit target to include only books with a photographed spine.
  const navigate = async delta => { const id=L[idx+delta]; if(!id)return; const full=NAV.list||L; const diff=full.indexOf(id)-full.indexOf(b.id); await goNav(diff); const target=books.find(o=>o.id===NAV.cur); if(target && target.id===id)openLoupe(target); };
  $('#lpPrev').onclick=()=>navigate(-1); $('#lpNext').onclick=()=>navigate(1);
  const key=e=>{if(!W.isConnected||!$('#modal').classList.contains('on')||/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();e.stopImmediatePropagation();navigate(e.key==='ArrowRight'?1:-1);}};
  document.addEventListener('keydown',key,true);
  modalExtraCleanup=()=>{window.removeEventListener('mousemove',mv);window.removeEventListener('mouseup',up);document.removeEventListener('keydown',key,true);};
}
