const origImport = b => { const id = b.srcRef?.imp || b.importId; return id ? imports.find(i => i.id === id) : null; };
async function readSpinesAI(list) {
  if (!cfg.key || !list.length) return;
  const parts = [{text: `Voici ${list.length} dos de livres (photos redressées et agrandies, texte souvent vertical, parfois à l'envers). Pour chaque image k, identifie l'ouvrage (édition française en priorité) ; tome LU sur l'image sinon null ; titre null si illisible.
JSON : [{"k":1,"titre":"…","auteur":"…","serie":null,"tome":null,"editeur":"…","type":"un parmi ${TYPES.join(', ')}"}]`}];
  list.forEach((m, k) => parts.push({text: 'Image k=' + (k + 1)}, {inlineData: {mimeType: 'image/jpeg', data: m.read.split(',')[1]}}));
  const rr = await gemini(parts, {json: true, think: 'low', timeout: 120000});
  (Array.isArray(rr) ? rr : (rr.livres || [])).forEach(o => { const m = list[(+o.k || 0) - 1]; if (m && o.titre) m.res = o; });
}
