  const fitAll = () => { const r = W.getBoundingClientRect(); z = Math.min(r.width / img.naturalWidth, r.height / img.naturalHeight) * .98; ox = (r.width - img.naturalWidth * z) / 2; oy = (r.height - img.naturalHeight * z) / 2; draw(); };
  const fitBook = () => { const r = W.getBoundingClientRect(); const Q = b.quad && (b.srcRef?.pi ?? 0) === pi ? quadPx(b.quad, img) : null; if (!Q) return fitAll();
    const bb = quadBox(Q), h = bb.y1 - bb.y0, w = bb.x1 - bb.x0; z = Math.min(r.height * .8 / h, r.width * .9 / (w + h * 1.2));
    ox = r.width / 2 - (bb.x0 + bb.x1) / 2 * z; oy = r.height / 2 - (bb.y0 + bb.y1) / 2 * z; draw(); };
