const defaultCase = () => cases.some(c => c.id === curCase) ? curCase : (cases[0]?.id || null);

/* =====================================================================
   AJOUT D'UN LIVRE : manuel, recherche par titre, code-barres / ISBN
   ===================================================================== */
function addManual() {
  openModal(`<div class="dhead"><h3>Ajouter un livre</h3><button class="x" data-close>×</button></div><div class="mbody">
    <div class="step"><i>1</i>Saisie manuelle</div>
    <p class="hint" style="margin-top:0">Ouvre une fiche vierge : tu choisis le meuble, l'étagère et la position (vide = à la fin de l'étagère).</p>
    <button class="btn g" id="aMan">Saisir le livre à la main</button>
    <div class="step" style="margin-top:20px"><i>2</i>Ou rechercher par titre / auteur</div>
    <div style="display:flex;gap:8px"><input class="fld" id="aQ" placeholder="ex. Le Seigneur des Anneaux Tolkien"><button class="btn p" id="aSearch">Rechercher</button></div>
    <div id="aRes"></div>
    <div class="step" style="margin-top:20px"><i>3</i>Ou par code-barres / ISBN</div>
    <div style="display:flex;gap:8px"><input class="fld" id="aIsbn" placeholder="978…"><button class="btn p" id="aGo">Rechercher</button><button class="btn s" id="aCam">Webcam</button></div>
    <div id="bcWrap" style="display:none;margin-top:12px"><div class="camwrap" style="aspect-ratio:16/9"><video id="bcVid" autoplay playsinline muted></video><div class="camframe" style="inset:22% 14%"><i></i><i></i><i></i><i></i></div></div>
      <div class="btns"><button class="btn p" id="bcRead">Lire le code</button><span class="hint" id="bcMsg" style="align-self:center">Présente le code-barres (au dos du livre) dans le cadre…</span></div></div>
  </div>`, 'sm');
  const fromItem = it => { const b = newBook({caseId: defaultCase()}); applyGB(b, it, true); b.title = it.volumeInfo?.title || ''; if (it.volumeInfo?.subtitle && !/tome/i.test(b.title)) b.subtitle = it.volumeInfo.subtitle; closeModal(); openBook(b, true); };
  let RES = [];
  const search = async () => { const q = $('#aQ').value.trim(); if (!q) return; $('#aRes').innerHTML = '<p class="hint"><span class="spin"></span> Recherche…</p>';
    RES = await gBooks(q, 6); $('#aRes').innerHTML = RES.length ? RES.map((it, i) => { const v = it.volumeInfo || {}, im = v.imageLinks?.smallThumbnail;
      return `<div class="res" data-res="${i}">${im ? `<img src="${esc(im.replace('http://', 'https://'))}" alt="">` : '<span class="ph"></span>'}<div><b>${esc(v.title || '')}</b>${v.subtitle ? ' – ' + esc(v.subtitle) : ''}<div class="hint">${esc((v.authors || []).join(', '))} · ${esc(v.publisher || '')} · ${esc((v.publishedDate || '').slice(0, 4))}</div></div></div>`; }).join('')
      : '<p class="hint">Aucun résultat : utilise la saisie manuelle.</p>'; };
  $('#aSearch').onclick = search; $('#aQ').onkeydown = e => e.key === 'Enter' && search();
  $('#aRes').onclick = e => { const r = e.target.closest('[data-res]'); if (r) fromItem(RES[+r.dataset.res]); };
  $('#aQ').focus();
  const go = async () => { const isbn = $('#aIsbn').value.replace(/[^0-9X]/gi, ''); if (isbn.length < 10) return toast('ISBN invalide');
    $('#aGo').innerHTML = '<span class="spin"></span>'; const items = await gBooks('isbn:' + isbn);
    const dup = books.find(x => x.isbn && x.isbn.replace(/\D/g, '') === isbn.replace(/\D/g, '') && !x.wish); if (dup) toast(`Tu possèdes déjà ce livre (${locOf(dup)})`, 5000);
    if (items[0]) return fromItem(items[0]);
    const b = newBook({isbn, caseId: defaultCase()}); toast('ISBN introuvable dans Google Books : complète la fiche'); closeModal(); openBook(b, true); };
  const found = code => { stopCam(); $('#aIsbn').value = code; toast('Code lu : ' + code); go(); };
  $('#aGo').onclick = go; $('#aIsbn').onkeydown = e => e.key === 'Enter' && go();
  $('#aMan').onclick = () => { closeModal(); openBook(newBook({caseId: defaultCase()}), true); };
  $('#aCam').onclick = async () => {
    $('#bcWrap').style.display = 'block';
    try { stopCam(); stream = await navigator.mediaDevices.getUserMedia({video: {facingMode: {ideal: 'environment'}, width: {ideal: 1280}, height: {ideal: 720}}, audio: false}); $('#bcVid').srcObject = stream; }
    catch (e) { return toast('Caméra inaccessible : ' + (e.name === 'NotAllowedError' ? 'autorisation refusée' : e.message), 4500); }
    let det = null;
    if ('BarcodeDetector' in window) { try { const fm = await window.BarcodeDetector.getSupportedFormats(); if (fm.includes('ean_13')) det = new window.BarcodeDetector({formats: ['ean_13', 'ean_8', 'upc_a']}); } catch (e) {} }
    $('#bcMsg').textContent = det ? 'Détection automatique en cours… (ou clique sur « Lire le code »)' : 'Clique sur « Lire le code » quand le code-barres est net (lecture par l\'IA).';
    if (det) { const loop = async () => { if (!stream || !$('#bcVid')) return; try { const r = await det.detect($('#bcVid')); const c = r.find(x => /^97[89]\d{10}$/.test(x.rawValue)) || r[0]; if (c) return found(c.rawValue); } catch (e) {} setTimeout(loop, 300); }; loop(); }
  };
  $('#bcRead').onclick = async () => { const v = $('#bcVid'); if (!v || !v.videoWidth) return; $('#bcMsg').innerHTML = '<span class="spin"></span> Lecture du code…';
    try { const o = await gemini([{text: 'Lis le code-barres EAN-13 / ISBN visible sur cette image (chiffres imprimés sous le code-barres, ou mention ISBN). Réponds en JSON {"isbn":"chiffres uniquement, ou null"}.'}, {inlineData: {mimeType: 'image/jpeg', data: resize(v, 1280, .92).split(',')[1]}}], {json: true});
      const n = String(o.isbn || '').replace(/[^0-9X]/gi, ''); if (n.length >= 10) found(n); else $('#bcMsg').textContent = 'Code non lu : rapproche le livre, évite les reflets et réessaie.';
    } catch (e) { $('#bcMsg').textContent = e.message; } };
  // V1.6 : recherche ISBN complète (Google Books + Open Library + IA) et lecteur commun
  $('#aGo').onclick = () => { const v = cleanIsbn($('#aIsbn').value); if (v.length !== 10 && v.length !== 13) return toast('ISBN invalide'); newFromIsbn(v); };
  $('#aIsbn').onkeydown = e => e.key === 'Enter' && $('#aGo').onclick();
  $('#aCam').onclick = () => openBarcode(newFromIsbn);
}

